SELECT p.\"sProject\", m.\"tmMessage\", m.\"sType\", LEFT(m.\"sContent\", 200) as content_preview FROM \"CC_Messages\" m JOIN \"CC_Sessions\" s ON m.\"iSessionId\" = s.\"iSessionId\" JOIN \"CC_Projects\" p ON s.\"iProjectId\" = p.\"iProjectId\" WHERE m.\"sContent\" ILIKE '%прогноз%' OR m.\"sContent\" ILIKE '%оптимальн%' OR m.\"sContent\" ILIKE '%точност%' OR m.\"sContent\" ILIKE '%лучш%' ORDER BY m.\"tmMessage\" ASC LIMIT 20